#Requires -Version 5.1
# Generated by Build-CodeEkoWarmup.cjs. Edit this template, then regenerate.
[CmdletBinding()]
param(
    [string]$Endpoint,
    [string]$Model,
    [Security.SecureString]$ApiKey,
    [ValidateSet('Full access', 'Workspace', 'Review')][string]$PermissionMode = 'Full access',
    [ValidateSet('User message', 'Standard')][string]$CompatibilityMode = 'User message',
    [ValidateRange(1, 100)][int]$RequestsPerBatch = 5,
    [ValidateRange(1, 12)][int]$Batches = 3,
    [ValidateRange(0, 3600)][int]$IdleSeconds = 600,
    [ValidateRange(1, 600)][int]$TimeoutSeconds = 300,
    [switch]$NoStreaming,
    [switch]$FreshConnections,
    [string]$OutputPath
)

$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Net.Http
if (!$Endpoint) { $Endpoint = Read-Host 'API base URL from CodeEko settings' }
if (!$Model) { $Model = Read-Host 'Exact upstream model ID from CodeEko settings' }
$Endpoint = $Endpoint.Trim().TrimEnd('/')
$Model = $Model.Trim()
if (!$Model) { throw 'A model ID is required.' }
$address = $null
if (![Uri]::TryCreate($Endpoint, [UriKind]::Absolute, [ref]$address) -or
    $address.Scheme -ne 'https' -or $address.UserInfo -or $address.Query -or $address.Fragment) {
    throw 'Use an HTTPS API base URL without credentials, query parameters or fragments.'
}
if ($address.AbsolutePath -notmatch '/v\d+(?:(?:alpha|beta)\d*)?(?:/|$)') { $Endpoint += '/v1' }
if (!$OutputPath) { $OutputPath = Join-Path $PWD ('codeeko-warmup-' + [DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0, 6) + '.json') }
$OutputPath = [IO.Path]::GetFullPath($OutputPath)
if (Test-Path -LiteralPath $OutputPath) { throw 'The output file already exists. Choose a new OutputPath.' }
if (!(Test-Path -LiteralPath ([IO.Path]::GetDirectoryName($OutputPath)) -PathType Container)) { throw 'The output directory must already exist.' }
if (!$ApiKey) { $ApiKey = Read-Host 'API key (hidden)' -AsSecureString }

$templateVersion = '0.4.57'
$profilesJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$profiles = ConvertFrom-Json -InputObject $profilesJson
$requestProfile = $profiles.PSObject.Properties[$PermissionMode + '|' + $CompatibilityMode].Value
$requestObject = [ordered]@{ model = $Model; messages = @($requestProfile.messages); temperature = 0; stream = !$NoStreaming; max_tokens = 4096 }
if ($CompatibilityMode -eq 'Standard') { $requestObject.response_format = @{ type = 'json_object' } }
$RequestBody = ConvertTo-Json -InputObject $requestObject -Depth 12 -Compress

function Read-WarmupMetadata {
    param($Data, $Report)
    foreach ($name in @('prompt_tokens', 'completion_tokens', 'total_tokens')) {
        $value = $Data.usage.$name
        if (($value -is [int] -or $value -is [long] -or $value -is [double]) -and $value -ge 0 -and $value -le 1e12) { $Report.usage[$name] = $value }
    }
    foreach ($choice in $Data.choices) {
        if ($null -ne $choice.index -and $choice.index -ne 0) { continue }
        if ($null -ne $choice.finish_reason) {
            $Report.finishReason = if ($choice.finish_reason -in @('stop', 'length', 'content_filter', 'tool_calls', 'function_call', 'MALFORMED_FUNCTION_CALL')) { $choice.finish_reason } else { 'other' }
        }
    }
}

function Wait-ProbeTask {
    param($Task, [Diagnostics.Stopwatch]$Watch)
    $remaining = ($TimeoutSeconds * 1000) - [int]$Watch.ElapsedMilliseconds
    if ($remaining -le 0 -or !$Task.Wait($remaining)) {
        throw [TimeoutException]::new('Probe deadline reached.')
    }
    $Task.GetAwaiter().GetResult()
}

function Get-ProbeFailure {
    param([Exception]$Exception, [string]$Stage)
    # Export only known type names and numeric codes, never exception messages,
    # stack traces, Data, request objects or arbitrary property strings.
    $allowed = @(
        'System.Management.Automation.MethodInvocationException',
        'System.Management.Automation.RuntimeException',
        'System.AggregateException', 'System.Net.Http.HttpRequestException',
        'System.Net.WebException', 'System.Net.Sockets.SocketException',
        'System.Security.Authentication.AuthenticationException',
        'System.IO.IOException', 'System.TimeoutException',
        'System.Threading.Tasks.TaskCanceledException', 'System.OperationCanceledException'
    )
    $queue = New-Object 'Collections.Generic.Queue[System.Exception]'
    $queue.Enqueue($Exception)
    $visited = 0
    $details = @(while ($queue.Count -gt 0 -and $visited -lt 12) {
        $current = $queue.Dequeue()
        $visited++
        $type = $current.GetType().FullName
        $entry = [ordered]@{
            type = $(if ($allowed -contains $type) { $type } else { 'OtherException' })
            hresult = [int]$current.HResult
        }
        if ($current -is [Net.WebException]) {
            $entry.webExceptionStatusCode = [int]$current.Status
            if ([Enum]::IsDefined([Net.WebExceptionStatus], $current.Status)) {
                $entry.webExceptionStatus = $current.Status.ToString()
            }
        }
        if ($current -is [Net.Sockets.SocketException]) {
            $entry.socketErrorCode = [int]$current.SocketErrorCode
            $entry.nativeErrorCode = [int]$current.NativeErrorCode
            if ([Enum]::IsDefined([Net.Sockets.SocketError], $current.SocketErrorCode)) {
                $entry.socketError = $current.SocketErrorCode.ToString()
            }
        }
        [PSCustomObject]$entry
        if ($current -is [AggregateException]) {
            foreach ($inner in $current.InnerExceptions) {
                if ($queue.Count -lt 12) { $queue.Enqueue($inner) }
            }
        } elseif ($current.InnerException) { $queue.Enqueue($current.InnerException) }
    })
    [PSCustomObject]@{ stage = $Stage; exceptions = $details }
}

function Receive-ProbeEvent {
    param([string]$Data, $State, $Report, [Diagnostics.Stopwatch]$Watch)
    if (!$Data.Trim()) { return }
    if ($Data.Trim() -eq '[DONE]') { $Report.doneMarker = $true; return }
    try { $item = ConvertFrom-Json -InputObject $Data -ErrorAction Stop }
    catch { $Report.malformedEvents++; return }
    $Report.events++
    Read-WarmupMetadata $item $Report
    if ($item.error) { $Report.providerError = $true }
    foreach ($choice in $item.choices) {
        if ($null -ne $choice.index -and $choice.index -ne 0) { continue }
        if ($choice.finish_reason) { $Report.finishReasonReceived = $true }
        $part = $choice.delta.content
        if ($part -is [string] -and $part.Length -gt 0) {
            $seconds = [Math]::Round($Watch.Elapsed.TotalSeconds, 3)
            if ($null -eq $Report.firstTextSeconds) { $Report.firstTextSeconds = $seconds }
            $Report.lastTextSeconds = $seconds
            $Report.contentChunks++
            if ($State.Times.Count -lt 20) { [void]$State.Times.Add($seconds) }
            [void]$State.Text.Append($part)
        }
    }
}

function Receive-ProbeLine {
    param([string]$Line, $State, $Report, [Diagnostics.Stopwatch]$Watch)
    if ($Line -eq '') {
        if ($State.Event.Length -gt 0) {
            Receive-ProbeEvent $State.Event.ToString() $State $Report $Watch
            [void]$State.Event.Clear()
        }
        return
    }
    if ($Line -match '^(data:|event:|id:|retry:|:)') { $State.Sse = $true }
    if ($Line.StartsWith('data:')) {
        $value = $Line.Substring(5)
        if ($value.StartsWith(' ')) { $value = $value.Substring(1) }
        if ($State.Event.Length -gt 0) { [void]$State.Event.Append("`n") }
        [void]$State.Event.Append($value)
    }
}

function Invoke-WarmupRequest {
    param([bool]$Streaming, [string]$Key, $SharedClient)
    $report = [ordered]@{
        test = $(if ($Streaming) { 'streaming' } else { 'normal' })
        atUtc = [DateTime]::UtcNow.ToString('o')
        usage = @{}
        finishReason = $null
        timeoutSeconds = $TimeoutSeconds
        httpStatus = $null
        advertisedEventStream = $false
        bodyFormat = 'unknown'
        headerBodyMismatch = $false
        headersSeconds = $null
        firstBodySeconds = $null
        firstTextSeconds = $null
        lastTextSeconds = $null
        totalSeconds = $null
        bodyCharacters = 0
        bodyBytes = 0
        bodyChunks = 0
        events = 0
        contentChunks = 0
        first20ContentChunkSeconds = @()
        contentCharacters = 0
        doneMarker = $false
        finishReasonReceived = $false
        malformedEvents = 0
        providerError = $false
        validJson = $false
        expectedAction = $false
        outcome = 'pending'
        failure = $null
    }
    $state = @{
        Sse = $false
        Event = New-Object Text.StringBuilder
        Text = New-Object Text.StringBuilder
        Times = New-Object 'Collections.Generic.List[double]'
    }
    $body = New-Object Text.StringBuilder
    $pending = ''
    $client = $SharedClient
    $request = New-Object Net.Http.HttpRequestMessage([Net.Http.HttpMethod]::Post, "$Endpoint/chat/completions")
    $response = $null
    $reader = $null
    $watch = [Diagnostics.Stopwatch]::StartNew()
    $stage = 'request'
    try {
        $request.Headers.Authorization = New-Object Net.Http.Headers.AuthenticationHeaderValue('Bearer', $Key)
        $payload = $RequestBody
        $request.Content = New-Object Net.Http.StringContent($payload, [Text.Encoding]::UTF8, 'application/json')
        $response = Wait-ProbeTask ($client.SendAsync($request, [Net.Http.HttpCompletionOption]::ResponseHeadersRead)) $watch
        $report.headersSeconds = [Math]::Round($watch.Elapsed.TotalSeconds, 3)
        $report.httpStatus = [int]$response.StatusCode
        $report.advertisedEventStream = $response.Content.Headers.ContentType.MediaType -eq 'text/event-stream'
        if (!$response.IsSuccessStatusCode) {
            $report.outcome = 'http-error'
        } else {
            $stage = 'body-read'
            $stream = Wait-ProbeTask ($response.Content.ReadAsStreamAsync()) $watch
            $reader = $stream
            $buffer = New-Object byte[] 4096
            $decoder = [Text.Encoding]::UTF8.GetDecoder()
            $characters = New-Object char[] 4096
            while (!$report.doneMarker) {
                $count = Wait-ProbeTask ($reader.ReadAsync($buffer, 0, $buffer.Length)) $watch
                if ($count -eq 0) { break }
                if ($null -eq $report.firstBodySeconds) {
                    $report.firstBodySeconds = [Math]::Round($watch.Elapsed.TotalSeconds, 3)
                }
                $report.bodyBytes += $count
                $report.bodyChunks++
                if ($report.bodyBytes -gt 1000000) {
                    $report.outcome = 'response-too-large'
                    break
                }
                $characterCount = $decoder.GetChars($buffer, 0, $count, $characters, 0, $false)
                $report.bodyCharacters += $characterCount
                $chunk = if ($characterCount -gt 0) { -join $characters[0..($characterCount - 1)] } else { '' }
                [void]$body.Append($chunk)
                $pending += $chunk
                # Detect SSE by its framing, regardless of the content-type header.
                while (($newline = $pending.IndexOf("`n")) -ge 0) {
                    $line = $pending.Substring(0, $newline).TrimEnd([char]13)
                    $pending = $pending.Substring($newline + 1)
                    Receive-ProbeLine $line $state $report $watch
                    if ($report.doneMarker) { break }
                }
            }
            if ($report.outcome -eq 'pending') {
                $stage = 'body-parse'
                if ($pending) { Receive-ProbeLine $pending $state $report $watch }
                if ($state.Event.Length -gt 0) { Receive-ProbeEvent $state.Event.ToString() $state $report $watch }
                if ($state.Sse) {
                    $report.bodyFormat = 'sse'
                    $report.headerBodyMismatch = !$report.advertisedEventStream
                    $report.outcome = if ($report.providerError) { 'provider-error' }
                        elseif ($report.malformedEvents) { 'malformed-sse' }
                        elseif (!$report.doneMarker -and !$report.finishReasonReceived) { 'incomplete-sse' }
                        else { 'stream-ended' }
                } else {
                    try { $data = ConvertFrom-Json -InputObject $body.ToString() -ErrorAction Stop }
                    catch { $report.outcome = 'body-not-json-or-sse'; $data = $null }
                    if ($null -ne $data) {
                        Read-WarmupMetadata $data $report
                        $report.bodyFormat = 'json'
                        $report.headerBodyMismatch = $report.advertisedEventStream
                        $report.providerError = [bool]$data.error
                        $part = $data.choices[0].message.content
                        if ($part -is [string] -and $part.Length -gt 0) {
                            [void]$state.Text.Append($part)
                            $report.contentChunks = 1
                            $report.firstTextSeconds = [Math]::Round($watch.Elapsed.TotalSeconds, 3)
                            $report.lastTextSeconds = $report.firstTextSeconds
                        }
                        $report.finishReasonReceived = [bool]$data.choices[0].finish_reason
                        $report.outcome = if ($report.providerError) { 'provider-error' }
                            elseif ($Streaming) { 'non-stream-response' } else { 'response-received' }
                    }
                }
                try {
                    $action = ConvertFrom-Json -InputObject $state.Text.ToString() -ErrorAction Stop
                    $report.validJson = $null -ne $action
                    $report.expectedAction = $action.version -eq 1 -and $action.tool -eq 'complete_task' -and $action.args.summary -is [string] -and $action.args.summary.Trim().Length -gt 0 -and @($action.PSObject.Properties).Count -eq 3 -and @($action.args.PSObject.Properties).Count -eq 1
                } catch { $report.validJson = $false; $report.expectedAction = $false }
            }
        }
    } catch {
        # Never print arbitrary transport exceptions, bodies, URLs or headers.
        $report.failure = Get-ProbeFailure $_.Exception $stage
        $report.outcome = if ($watch.ElapsedMilliseconds -ge ($TimeoutSeconds * 1000)) { 'timeout' }
            elseif ($stage -eq 'body-read') { 'body-read-error' }
            elseif ($stage -eq 'body-parse') { 'body-parse-error' }
            else { 'request-error' }
    } finally {
        $report.totalSeconds = [Math]::Round($watch.Elapsed.TotalSeconds, 3)
        $report.contentCharacters = $state.Text.Length
        $report.first20ContentChunkSeconds = @($state.Times.ToArray())
        if ($state.Sse) { $report.bodyFormat = 'sse'; $report.headerBodyMismatch = !$report.advertisedEventStream }
        $client.CancelPendingRequests()
        if ($reader) { $reader.Dispose() }
        if ($response) { $response.Dispose() }
        $request.Dispose()
    }
    [PSCustomObject]$report
}

function Get-WarmupClient {
    $handler = New-Object Net.Http.HttpClientHandler
    $handler.AllowAutoRedirect = $false
    $client = New-Object Net.Http.HttpClient($handler)
    $client.Timeout = [TimeSpan]::FromMilliseconds(-1)
    if ($FreshConnections) { $client.DefaultRequestHeaders.ConnectionClose = $true }
    return $client
}

function Get-WarmupMedian {
    param([object[]]$Values)
    $sorted = @($Values | Sort-Object)
    if (!$sorted.Count) { return $null }
    $middle = [int][Math]::Floor($sorted.Count / 2)
    if ($sorted.Count % 2) { return $sorted[$middle] }
    return [Math]::Round(($sorted[$middle - 1] + $sorted[$middle]) / 2, 3)
}

function Save-WarmupReport {
    $report.updatedAtUtc = [DateTime]::UtcNow.ToString('o')
    $report.summary = @(foreach ($batch in 1..$Batches) {
        $rows = @($results | Where-Object { $_.batch -eq $batch })
        if (!$rows.Count) { continue }
        $valid = @($rows | Where-Object { $_.validReply })
        $repeated = @($valid | Where-Object { $_.position -gt 1 })
        [PSCustomObject]@{ batch = $batch; attempted = $rows.Count; validReplies = $valid.Count
            invalidOrFailed = $rows.Count - $valid.Count; firstRequestValid = $rows[0].validReply
            firstRequestSeconds = $rows[0].totalSeconds
            repeatedValidMedianSeconds = Get-WarmupMedian @($repeated | ForEach-Object { $_.totalSeconds })
            validMedianFirstTextSeconds = Get-WarmupMedian @($valid | ForEach-Object { $_.firstTextSeconds }) }
    })
    $report.results = @($results.ToArray())
    $json = ConvertTo-Json -InputObject $report -Depth 12
    $temporary = $OutputPath + '.' + [Guid]::NewGuid().ToString('N') + '.tmp'
    try {
        [IO.File]::WriteAllText($temporary, $json, (New-Object Text.UTF8Encoding($false)))
        Move-Item -LiteralPath $temporary -Destination $OutputPath -Force
    } finally { if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary } }
}

$results = New-Object 'Collections.Generic.List[object]'
$report = [ordered]@{ warmupProbeVersion = 1; requestTemplateVersion = $templateVersion
    startedAtUtc = [DateTime]::UtcNow.ToString('o'); updatedAtUtc = $null; completed = $false; state = 'starting'
    transport = 'PowerShell System.Net.Http.HttpClient'; powerShellVersion = $PSVersionTable.PSVersion.ToString()
    note = 'Exact synthetic fresh-chat hello message templates; no repository context, model actions, retries or accumulated history. Idle periods make no probe requests; they do not guarantee a cold server or flushed cache. PowerShell transport differs from VS Code.'
    settings = @{ requestsPerBatch = $RequestsPerBatch; batches = $Batches; idleSeconds = $IdleSeconds; timeoutSeconds = $TimeoutSeconds
        permissionMode = $PermissionMode; compatibilityMode = $CompatibilityMode; streaming = !$NoStreaming; temperature = 0; maxOutputTokens = 4096
        connectionPolicy = $(if ($FreshConnections) { 'new-client-per-request-and-connection-close' } else { 'reuse-client-across-all-batches' }) }
    messageDigest = $requestProfile.messageDigest; promptCharacters = (@($requestProfile.messages | ForEach-Object { $_.content.Length }) | Measure-Object -Sum).Sum
    waits = @(); summary = @(); results = @()
}
$pointer = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($ApiKey)
try { $plainKey = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer) }
finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer) }
if ($Model -match '^(?:models/)?[a-zA-Z0-9][a-zA-Z0-9._-]{0,149}$' -and (!$plainKey -or !$Model.Contains($plainKey))) { $report.model = $Model }
$sharedClient = $null
try {
    Save-WarmupReport
    Write-Output ('Report: ' + $OutputPath)
    if (!$FreshConnections) { $sharedClient = Get-WarmupClient }
    for ($batch = 1; $batch -le $Batches; $batch++) {
        if ($batch -gt 1 -and $IdleSeconds -gt 0) {
            $report.state = 'waiting'; Save-WarmupReport
            Write-Output ('Waiting {0} seconds before batch {1}/{2}...' -f $IdleSeconds, $batch, $Batches)
            $idleStart = [DateTime]::UtcNow.ToString('o')
            $idleWatch = [Diagnostics.Stopwatch]::StartNew()
            while ($idleWatch.Elapsed.TotalSeconds -lt $IdleSeconds) {
                Write-Progress -Activity 'CodeEko API warm-up test' -Status ('Idle: {0} seconds remaining' -f [Math]::Ceiling($IdleSeconds - $idleWatch.Elapsed.TotalSeconds))
                Start-Sleep -Milliseconds 250
            }
            $report.waits += [PSCustomObject]@{ beforeBatch = $batch; startedAtUtc = $idleStart; elapsedSeconds = [Math]::Round($idleWatch.Elapsed.TotalSeconds, 3) }
        }
        for ($position = 1; $position -le $RequestsPerBatch; $position++) {
            $report.state = 'requesting'; Save-WarmupReport
            Write-Output ('Batch {0}/{1}, request {2}/{3}' -f $batch, $Batches, $position, $RequestsPerBatch)
            $requestClient = if ($FreshConnections) { Get-WarmupClient } else { $sharedClient }
            try { $result = Invoke-WarmupRequest (!$NoStreaming) $plainKey $requestClient }
            finally { if ($FreshConnections -and $requestClient) { $requestClient.Dispose() } }
            $result | Add-Member -NotePropertyName batch -NotePropertyValue $batch
            $result | Add-Member -NotePropertyName position -NotePropertyValue $position
            $valid = $result.expectedAction -and $result.finishReason -eq 'stop' -and $result.outcome -in @('stream-ended', 'response-received', 'non-stream-response')
            $result | Add-Member -NotePropertyName validReply -NotePropertyValue ([bool]$valid)
            [void]$results.Add($result)
            Save-WarmupReport
            Write-Output ('  {0}s; valid reply: {1}; outcome: {2}' -f $result.totalSeconds, $result.validReply, $result.outcome)
        }
    }
    $report.completed = $true; $report.state = 'complete'; Save-WarmupReport
    Write-Output ('Finished. Send this JSON report: ' + $OutputPath)
} finally {
    if ($sharedClient) { $sharedClient.Dispose() }
    $plainKey = $null
    Write-Progress -Activity 'CodeEko API warm-up test' -Completed
    # Per-request checkpoints survive Ctrl+C or process termination.
}
